/// <summary>
/// Check if wave details need to be created in the system for the sales order
/// </summary>
/// <param name = "_salesTable">Table buffer of of <t>SalesTable</t></param>
/// <param name = "_inventLocation">Table buffer of type <t>InventLocation</t></param>
/// <returns>true if wave is required, otherwise false</returns>
private boolean isWaveRequired(SalesTable _salesTable, InventLocation _inventLocation)
{
    boolean ret = false;

    if (_salesTable.salesid && DateTimeUtil::minValue() != _salesTable.METOrderExtractDateTime
            && _inventLocation.METWaveRequired == NoYes::Yes) //Bug 189021: CB123 - METCSDWarehouse = Yes & METPickDirector = yes conditions are removed.
    {
        ret = true;
    }

    return ret;
}

public int getTotalCountOfLinesForSalesOrder(SalesId _salesId)
{
    SalesLine    salesLine;
    METSalesLine metSalesLine;

    select count(RecId) from salesLine
        where salesLine.SalesId == _salesId
            && salesLine.SalesStatus != SalesStatus::Canceled
        exists join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
                && metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted;

    return salesLine.RecId;
}

/// <summary>
/// Resets the processing flag in case of failure or successful batch job execution
/// </summary>
/// <param name = "_salesId">Sales Id</param>
private void resetProcessingFlag(SalesId _salesId)
{
    SalesTable salesTableLoc;
    ttsbegin;
    select firstonly forupdate salesTableLoc where salesTableLoc.SalesId == _salesId;
    if (salesTableLoc.RecId && salesTableLoc.METProcessing == NoYes::Yes)
    {
        salesTableLoc.METProcessing = NoYes::No;
        salesTableLoc.update();
    }
    ttscommit;
}

/// <summary>
/// processing logic
/// </summary>
/// <param name = "_dataContract">The data contract</param>
public void process(METSalesPickingListGenerationTaskContract _dataContract)
{
    #OCCRetryCount
    try
    {
        procMetrics = METProcMetrics::construct(METBatchLogOperation::SalesOrderExtractJob);
        procMetrics.startTrace(1, _dataContract.parmSalesId());
        procMetrics.incLineCount(this.getTotalCountOfLinesForSalesOrder(_dataContract.parmSalesId()));

        using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
        {
            METCustParameters metCustParameters = METCustParameters::find();
            useLegacyMode = metCustParameters.SalesExtractionPerfMode;
            useLegacyPostProcessMode = metCustParameters.SalesExtractionPostProcessPerfMode;
            batchTransactionCommit = metCustParameters.SalesExtractionBatchTransactionCommit;
            this.processPickingList(_dataContract);

            METBatchMonitoringStatus batchStatus = isError ? METBatchMonitoringStatus::Failed : METBatchMonitoringStatus::Completed;
            procMetrics.endTrace(batchStatus);
        }

    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch(Exception::DuplicateKeyException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::DuplicateKeyExceptionNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::DuplicateKeyException;
        }
    }
    //CBNF019_Observability_SalesOrderExtraction
    catch (Exception::Error)
    {
        str errorMessage;
        SysInfologEnumerator enumerator;
        SysInfologMessageStruct msgStruct;

        // 1. Extract error messages from the Infolog
        enumerator = SysInfologEnumerator::newData(infolog.copy(1, infologLine()));
        while (enumerator.moveNext())
        {
            msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
            errorMessage += msgStruct.message() + " ";
        }

        if (_dataContract && _dataContract.parmSalesId() != '')
        {
            METTelemetrySOExtractionErrorEvent::runTelemetryEvent(_dataContract.parmSalesId(), errorMessage);
        }
    }
    //CBNF019_Observability_SalesOrderExtraction
    catch
    {
        exceptionTextFallThrough();
    }
    finally
    {
        this.resetProcessingFlag(_dataContract.parmSalesId());
    }
}

/// <summary>
/// Process the picking list operations
/// </summary>
/// <param name = "_dataContract">Data contract reference</param>
public void processPickingList(METSalesPickingListGenerationTaskContract _dataContract)
{
    boolean     pickListForOrderedQty = false;
    companyInfo  = CompanyInfo::find();
    this.initParms(_dataContract);

    if (_dataContract.parmTriggerBusinessEvent())
    {
        this.finalThreadBusinessEventAndShipmentCleanup();

        return;
    }

    if (salesTable)
    {
        if (procMetrics)
        {
            procMetrics.startDescriptionTime(2, "@MET:METSOExtractSOGuideCheck");
        }

        this.performSOGuideCheck();

        if (procMetrics)
        {
            procMetrics.endDescriptionTime(2);
        }

        //Task 162245-CB123 - SalesOrderExtractScreenforCSD- start

        inventParameter = InventParameters::find();
        inventLocation = InventLocation::find(salesTable.InventLocationId);

        //Task 162245-CB123 - SalesOrderExtractScreenforCSD
        if (this.isWaveRequired(salesTable, inventLocation))
        {
            salesTable.createWaveFromSalesTable(inventLocation.METPickDirector, salesOrderCount, _dataContract.parmCsdGuid());
        }

        actionToPerform = this.getActionToPerform(salesTable);

        if (actionToPerform == METConstants::SOExtractCreateOnlyTO)
        {
            // If the supply from transfer option is enabled,
            // 1. Do not attempt stock reservation on local warehouse.
            // 2. create TO for the whole sales order quantity from NDC to CSD warehouse.

            if (procMetrics)
            {
                procMetrics.startDescriptionTime(3, "@MET:METSOExtractTransferOrderCreate");
            }

            METCrossDockTransferOrderProcessorBase::construct(salesTable).CreateTransferOrder();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(3, 1);
                procMetrics.endDescriptionTime(3);
            }

            info(strFmt("@MET:TOCreatedForSO", salesTable.SalesId));
        }
        else if (actionToPerform == METConstants::SOExtractReservedSOPickAndTO)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(3, "@MET:METSOExtractStockReservation");
            }

            METStockReservation::construct(salesTable).processV2();

            if (procMetrics)
            {
                procMetrics.endDescriptionTime(3);
            }

            if (useLegacyMode == NoYes::Yes)
            {
                this.postPickingList(salesTable);
            }
            else
            {
                this.postPickingListV2(salesTable);
            }

            //Intercompany picking list.
            this.postIntercompanyPickingList();

            if (useLegacyPostProcessMode)
            {
                if (procMetrics)
                {
                    procMetrics.startDescriptionTime(9, "@MET:METSOExtractCrossDockTransferOrder");
                }

                METCrossDockTransferOrderProcessorBase::construct(salesTable).CreateTransferOrder();

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(9, 1);
                    procMetrics.endDescriptionTime(9);
                }
            }
        }
        else if (actionToPerform == METConstants::SOExtractOrderedSOPickOnly)
        {
            //Post picking list
            if (useLegacyMode == NoYes::Yes)
            {
                this.postPickingList(salesTable, true);
            }
            else
            {
                this.postPickingListV2(salesTable, true);
            }

            //Post intercompany picking list. Sourcing all lines from a single company
            this.postIntercompanyPickingList();
        }
        else if (actionToPerform == METConstants::SOExtractReservedSOPickOnly)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(3, "@MET:METSOExtractStockReservation");
            }

            METStockReservation::construct(salesTable).processV2();

            if (procMetrics)
            {
                procMetrics.endDescriptionTime(3);
            }

            //Post picking list
            if (useLegacyMode == NoYes::Yes)
            {
                this.postPickingList(salesTable);
            }
            else
            {
                this.postPickingListV2(salesTable);
            }

            //Post intercompany picking list. Sourcing all lines from a single company
            this.postIntercompanyPickingList();
        }
        else if (actionToPerform == METConstants::SOExtractUpdateStatusOnly)
        {
            METSalesLine    metSalesLine;
            SalesLine       salesLineUpdate;

            ttsbegin;
            salesTable.reread();
            salesTable.selectForUpdate(true);
            salesTable.skipDatabaseLog(true);
            salesTable.skipDataMethods(true);   
            salesTable.SkipUpdate = true;
            salesTable.SkipLineUpdate = true;
            salesTable.METOrderExtractStatus = METOrderExtractStatus::Extracted;
            salesTable.METOrderExtractDateTime = DateTimeUtil::getSystemDateTime();
            salesTable.update();

            update_recordset metSalesLine
                setting OrderExtractStatus = METOrderExtractStatus::Extracted
                    exists join salesLineUpdate
                        where salesLineUpdate.RecId == metSalesLine.SalesLine &&
                            salesLineUpdate.SalesId == salesTable.SalesId;

            ttscommit;

            info(strFmt("@MET:SOExtractionUpdate", salesTable.SalesId));
        }
        else if (actionToPerform == METConstants::SOExtractSkip)
        {
            warning(strFmt("@MET:NoActionSOExtract", salesTable.SalesId));
        }
    }
}

/// <summary>
/// Initialize parameters requried for processing picking lists
/// </summary>
/// <param name = "_dataContract">The data contract</param>
public void initParms(METSalesPickingListGenerationTaskContract _dataContract)
{
    dataContract    =   _dataContract;
    salesTable      =   salesTable::find(_dataContract.parmSalesId());
    salesOrderCount =   dataContract.parmCSDSalesOrderCount();
}

/// <summary>
/// Post intercompany picking list
/// </summary>
private void postIntercompanyPickingList()
{
    PurchTable                      purchTable_Reference    = salesTable.referencePurchTable();

    if ((!purchTable_Reference.RecId && !purchTable_Reference.InterCompanySalesId) || !TradeInterCompany::checkDataAreaAccess(purchTable_Reference.InterCompanyCompanyId))
    {
        return;
    }
    else if (purchTable_Reference.RecId)
    {
        if (procMetrics)
        {
            procMetrics.startDescriptionTime(10, "@MET:METSOExtractIntercompanyPickingList");
        }

        changeCompany(purchTable_Reference.InterCompanyCompanyId)
        {
            METStockReservation::construct(purchTable_Reference.interCompanySalesTable()).processV2();

            if (useLegacyMode == NoYes::Yes)
            {
                this.postPickingList(purchTable_Reference.interCompanySalesTable(), false);
            }
            else
            {
                this.postPickingListV2(purchTable_Reference.interCompanySalesTable(), false);
            }

            this.finalThreadBusinessEventAndShipmentCleanup(true);
        }

        if (procMetrics)
        {
            procMetrics.incDescriptionCount(10, 1);
            procMetrics.endDescriptionTime(10);
        }
    }

}

/// <summary>
/// Post picking list
/// </summary>
/// <param name = "_salesTable">SalesTable buffer.</param>
/// <param name = "_pickListOrderedQty">boolean buffer.</param>
public void postPickingList(SalesTable _salesTable, boolean _pickListOrderedQty = false)
{
    QueryRun            queryRun;
    SalesTable          salesTableCurr = SalesTable::find(_salesTable.SalesId);
    SalesParmLine       salesParmLine;
    SalesFormLetter     salesFormLetter;
    MetShipmentId       shipmentId;

    try
    {
        // Bug 252392: CB173 - SO Extract attempting to create pick list on cancelled SO / lines
        if (salesTableCurr.SalesStatus != SalesStatus::Canceled)
        {
            // Reset processExtraction flag
            processExtraction = false;

            //NS-Created for CB274 - Intercompany Transfers.
            queryRun = this.calcQuery(_salesTable, _pickListOrderedQty);
            //NE-Created for CB274 - Intercompany Transfers.

            if (processExtraction == true)
            {
                ttsbegin;
                salesFormLetter = SalesFormLetter::construct(DocumentStatus::PickingList);

                salesFormLetter.chooseLinesQuery(queryRun);
                salesFormLetter.salesTable(_salestable);
                salesFormLetter.initParmSalesTable(salesFormLetter.salesTable());
                salesFormLetter.transDate(DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
                salesFormLetter.specQty(SalesUpdate::All);
                salesFormLetter.printFormLetter(salesFormLetter.printFormLetter());
                salesFormLetter.createParmUpdateFromParmUpdateRecord(SalesFormletterParmData::initSalesParmUpdateFormletter(salesFormLetter.documentStatus(), salesFormLetter.pack()));

                if (_pickListOrderedQty == false)
                {
                    //For intercompany orders we always pick the reserved quantity
                    if (!InventLocation::find(salesFormLetter.salesTable().InventLocationId).METPickDirector || _salesTable.InterCompanyOrder)
                    {
                        salesFormLetter.salesParmUpdate().ReduceOnHand  = NoYes::Yes;
                        salesFormLetter.salesParmUpdate().Reserve       = NoYes::Yes;
                    }
                }
                else
                {
                    salesFormLetter.salesParmUpdate().ReduceOnHand  = NoYes::No;
                    salesFormLetter.salesParmUpdate().Reserve       = NoYes::No;
                }
                // CB123 - SalesOrderExtractScreenforCSD -start
                // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
                // When called from TO finalisation, there is no instance of dataContract
                if (dataContract && dataContract.parmCSDSalesId() == dataContract.parmSalesId())
                {
                    salesFormLetter.initParameters(salesFormLetter.salesParmUpdate(), Printout::Current, NoYes::Yes, NoYes::No, NoYes::No ,NoYes::Yes);
                }
                else
                {
                    salesFormLetter.initParameters(salesFormLetter.salesParmUpdate(), Printout::Current);
                }
                // CB123 - SalesOrderExtractScreenforCSD -end
                salesFormLetter.initLinesQuery();


                if (_pickListOrderedQty == false)
                {
                    SalesLine salesLineLoc;

                    while select forupdate salesParmLine
                        where salesParmLine.ParmId == salesFormLetter.parmId()
                    {
                        salesLineLoc = salesParmLine.salesLine();

                        // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
                        // Refactor this part as slightly different for xDock
                        this.updateSalesParmLine(salesParmLine, salesLineLoc);
                    }

                    // Bug 252392: CB173 - SO Extract attempting to create pick list on cancelled SO / lines
                    // moved the info from caller method processPickingList to inside here
                    info(strFmt("@MET:PickListForReservedQty", salesTable.SalesId));
                }
                else
                {
                    Info(strfmt("@MET:SOPickListForOrderQty", _salesTable.SalesId));
                }

                salesFormLetter.run();

                METOrderShipmentLoadCreation shipmentLoadCreation =
                    METOrderShipmentLoadCreation::construct(METOrderTransactionType::SalesOrder, _salesTable.SalesId);

                shipmentId = shipmentLoadCreation.createShippmentLoad(true,false);

                select firstonly wmsPickingRoute
                    where wmsPickingRoute.parmid == salesFormLetter.parmId();

                if (wmsPickingRoute)
                {
                    // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
                    // update some extra fields when SO extract is called from TO finalisation
                    this.updateWmsPickingRoute(wmsPickingRoute);
                }                    
                ttscommit;
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error ("@WAX:UpdateCancelled");
                isError = true;
            }
            else
            {
                retry;
            }
        }
        else
        {
            error ("@WAX:UpdateCancelled");
            isError = true;
        }
    }
    catch(Exception::DuplicateKeyException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error ("@WAX:UpdateCancelled");
                isError = true;
            }
            else
            {
                retry;
            }
        }
        else
        {
            error ("@WAX:UpdateCancelled");
            isError = true;
        }
    }
    catch
    {
        error ("@WAX:UpdateCancelled");
        isError = true;
    }

    salesTableCurr.reread();
    salesTableCurr.selectForUpdate(true);
    salesTableCurr.metUpdateExtractStatus();

    if (!isError && !skipTMSProcess)
    {
        //CB625_TMSSOPickingListExtraction
        if (salesTableCurr.METOrderExtractStatus == METOrderExtractStatus::Extracted)
        {
            METTMSEngineOrderProccess  metTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderPickingList, wmsPickingRoute, wmsPickingRoute.PickingRouteID);
            metTMSEngineOrderProccess.run();
        }
    }
}

/// <summary>
/// Created for the CB274 - Intercompany Transfers.
/// Exclude the SO  line for extraction if it's a food item.
/// Create a Purchase order for the food item line.
/// </summary>
/// <param name = "_salesTable">Sales Id reference</param>
/// <param name = "_pickListOrderedQty">Set to yes if picking list to be generated by ordered qty</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(SalesTable _salesTable, boolean   _pickListOrderedQty)
{
    Query                   qry = new Query(QueryStr(SalesUpdate));
    RefRecId                salesLineRecId;
    SalesLine               salesLine;
    METSalesLine            metSalesLine, metSalesLineNotExtracted;
    QueryBuildRange         qbrSalesLine;
    QueryBuildDataSource    qbdsSalesLine;
    boolean                 interCompanyPOCreated = false;
    PurchLine               purchLineRef;

    InventLocation inventLocationLoc;
    InventDim inventDim;
    qbdsSalesLine = qry.dataSourceTable(tableNum(SalesLine));

    while select forupdate salesLine
        where salesLine.SalesId == _salesTable.SalesId
            && salesLine.SalesStatus != SalesStatus::Canceled
        join OrderExtractStatus from metSalesLineNotExtracted
            where metSalesLineNotExtracted.SalesLine == salesLine.RecId
        join inventdim
            where inventDim.inventDimId == salesLine.inventDimId
        join inventLocationLoc
            where inventLocationLoc.InventLocationId == inventDim.inventLocationId &&
            ( metSalesLineNotExtracted.OrderExtractStatus != METOrderExtractStatus::Extracted ||
            ((metSalesTable.InternalCrossDockOrder == true && metSalesLineNotExtracted.OrderExtractStatus == METOrderExtractStatus::Extracted) ||
            (inventLocationLoc.METCSDWarehouse == true && metSalesLineNotExtracted.OrderExtractStatus == METOrderExtractStatus::Extracted)))

    {
        purchLineRef = salesLine.referencedPurchLine();

        if (interCompanyPOCreated == false && salesLine.referencedPurchLine().RecId == 0 && InventTable::metGetOSCCode(salesLine.ItemId, inventDim) == METConstants::GroceryOscCode &&
            _salesTable.METIntercompanyTransferFulfillment == NoYes::Yes
            && _salesTable.InterCompanyOrigin != InterCompanyOrigin::Derived)
        {
            METSalesOrderProcessHelper::createPOForIntercompanyFulfillment(_salesTable, salesLine);
            interCompanyPOCreated = true;
        }
        else if (salesLine.referencedPurchLine().RecId != 0)
        {
            continue;
        }
        else
        {
            // Bug 297848: CB679 SO line cancelled & Back order not created
            // when called from METCrossDockSalesFinalizationFacade\postPickingList, salesTable is never set, use the method parameter instead
            // otherwise the open line for extraction gets cancelled
            //if (this.cancelSalesLine(salesTable, salesLine, _pickListOrderedQty))
            if (this.cancelSalesLine(_salesTable, salesLine, _pickListOrderedQty))
            {
                if (salesLine.inventTable().pdsCWItem())
                {
                    SalesUpdateRemain::construct().updateCatchWeightDeliverRemainder(salesLine, 0);
                }
                else
                {
                    SalesUpdateRemain::construct().updateDeliverRemainder(salesLine, 0, 0);
                }

                info(strFmt("@MET:NoStock", salesLine.SalesId, salesLine.ItemId));

                update_recordset metSalesLine
                    setting OrderExtractStatus = METOrderExtractStatus::Extracted
                        where metSalesLine.SalesLine == salesLine.RecId &&
                              metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted;
            }
            else
            {
                if (_pickListOrderedQty == false && salesLine.reservedPhysicalInSalesUnit() == 0)
                {
                    continue;
                }
                processExtraction   = true;
                salesLineRecId      = salesLine.RecId;
                qbrSalesLine        = qbdsSalesLine.addRange(fieldnum(SalesLine, RecId));

                qbrSalesLine.value(SysQuery::value(salesLineRecId));
            }
        }
    }
    return new sysQueryRun(qry);
}

private SalesUpdateRemain salesUpdateRemain()
{
    if (salesUpdateRemain == null)
    {
        salesUpdateRemain = SalesUpdateRemain::construct();
        salesUpdateRemain.metParmIsExtraction(true);
    }

    return salesUpdateRemain;
}

/// <summary>
/// Created for the CB274 - Intercompany Transfers.
/// Exclude the SO  line for extraction if it's a food item.
/// Create a Purchase order for the food item line.
/// </summary>
/// <param name = "_salesTable">Sales Id reference</param>
/// <param name = "_pickListOrderedQty">Set to yes if picking list to be generated by ordered qty</param>
/// <returns>SysQueryRun</returns>
private List calcQueryV2(SalesTable _salesTable, boolean _pickListOrderedQty)
{
    SalesLine               salesLine;
    METSalesLine            metSalesLine, metSalesLineNotExtracted;
    boolean                 interCompanyPOCreated = false;
    PurchLine               purchLineRef, purchLineRefJoin;
    InventLocation          inventLocationLoc;
    InventDim               inventDim;
    List                    qualifyingSalesLines = new List(Types::Int64);
    int                     batchCount = 0;
    boolean                 batchOpen  = false;

    while select forupdate salesLine
        where salesLine.SalesId == _salesTable.SalesId
            && salesLine.SalesStatus != SalesStatus::Canceled
        join forupdate metSalesLineNotExtracted
            where metSalesLineNotExtracted.SalesLine == salesLine.RecId
        join inventdim
            where inventDim.inventDimId == salesLine.inventDimId
        join inventLocationLoc
            where inventLocationLoc.InventLocationId == inventDim.inventLocationId &&
            ( metSalesLineNotExtracted.OrderExtractStatus != METOrderExtractStatus::Extracted ||
            ((metSalesTable.InternalCrossDockOrder == true && metSalesLineNotExtracted.OrderExtractStatus == METOrderExtractStatus::Extracted) ||
            (inventLocationLoc.METCSDWarehouse == true && metSalesLineNotExtracted.OrderExtractStatus == METOrderExtractStatus::Extracted)))
        outer join purchLineRefJoin
            where purchLineRefJoin.InventTransId == salesLine.InventRefTransId
    {
        if (purchLineRefJoin.RecId && salesLine.InventRefTransId && salesLine.InventRefType == InventRefType::Purch && !purchLineRefJoin.IsDeleted)
        {
            purchLineRef = purchLineRefJoin;
        }

        if (interCompanyPOCreated == false
            && purchLineRef.RecId == 0
            && InventTable::metGetOSCCode(salesLine.ItemId, inventDim) == METConstants::GroceryOscCode
            && _salesTable.METIntercompanyTransferFulfillment == NoYes::Yes
            && _salesTable.InterCompanyOrigin != InterCompanyOrigin::Derived)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(4, "@MET:METSOExtractICPOCreation");
            }

            METSalesOrderProcessHelper::createPOForIntercompanyFulfillment(_salesTable, salesLine);
            interCompanyPOCreated = true;

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(4, 1);
                procMetrics.endDescriptionTime(4);
            }
        }
        else if (purchLineRef.RecId != 0)
        {
            continue;
        }
        else
        {
            if (useLegacyPostProcessMode)
            {
                if (this.cancelSalesLineV2(_salesTable, salesLine, _pickListOrderedQty))
                {
                    if (procMetrics)
                    {
                        procMetrics.startDescriptionTime(5, "@MET:METSOExtractDeliverRemainderCancel");
                    }

                    if (!batchOpen)
                    {
                        this.ttsBeginTrace();
                        batchOpen = true;
                    }

                    if (metSalesLineNotExtracted.OrderExtractStatus != METOrderExtractStatus::Extracted)
                    {
                        metSalesLineNotExtracted.skipBusinessEvents(true);
                        metSalesLineNotExtracted.OrderExtractStatus = METOrderExtractStatus::Extracted;
                        metSalesLineNotExtracted.doUpdate();
                    }

                    if (salesLine.inventTable().pdsCWItem())
                    {
                        this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0);
                    }

                    info(strFmt("@MET:NoStock", salesLine.SalesId, salesLine.ItemId));

                    batchCount++;

                    if (batchCount >= batchTransactionCommit)
                    {
                        this.ttsCommitTrace(5);

                        batchOpen = false;
                        batchCount = 0;
                    }

                    if (procMetrics)
                    {
                        procMetrics.incDescriptionCount(5, 1);
                        procMetrics.endDescriptionTime(5);
                    }
                }
                else
                {
                    SalesQtyReservPhysical reservQtyinSalesUnit;
                    SalesQtyReservPhysical reservQtyinInventUnit;

                    if (reservedQtyInSalesUnitMap.exists(salesLine.RecId))
                    {
                        reservQtyinSalesUnit = reservedQtyInSalesUnitMap.lookup(salesLine.RecId);
                        reservQtyinInventUnit = reservedQtyInInventUnitMap.lookup(salesLine.RecId);
                    }
                    else
                    {
                        container reservedQty = salesLine.metReservedPhysicalInSalesInventUnit();

                        reservQtyinSalesUnit = conPeek(reservedQty, 1);
                        reservQtyinInventUnit = conPeek(reservedQty, 2);

                        reservedQtyInSalesUnitMap.add(salesLine.RecId, reservQtyinSalesUnit);
                        reservedQtyInInventUnitMap.add(salesLine.RecId, reservQtyinInventUnit);
                    }

                    if (_pickListOrderedQty == false && reservQtyinSalesUnit == 0)
                    {
                        continue;
                    }

                    processExtraction = true;
                    qualifyingSalesLines.addEnd(salesLine.RecId);
                }
            }
            else
            {
                SalesQtyReservPhysical reservQtyinSalesUnit;
                SalesQtyReservPhysical reservQtyinInventUnit;

                if (reservedQtyInSalesUnitMap.exists(salesLine.RecId))
                {
                    reservQtyinSalesUnit = reservedQtyInSalesUnitMap.lookup(salesLine.RecId);
                    reservQtyinInventUnit = reservedQtyInInventUnitMap.lookup(salesLine.RecId);
                }
                else
                {
                    container reservedQty = salesLine.metReservedPhysicalInSalesInventUnit();

                    reservQtyinSalesUnit = conPeek(reservedQty, 1);
                    reservQtyinInventUnit = conPeek(reservedQty, 2);

                    reservedQtyInSalesUnitMap.add(salesLine.RecId, reservQtyinSalesUnit);
                    reservedQtyInInventUnitMap.add(salesLine.RecId, reservQtyinInventUnit);
                }

                if (_pickListOrderedQty == false && reservQtyinSalesUnit == 0)
                {
                    continue;
                }

                processExtraction = true;
                qualifyingSalesLines.addEnd(salesLine.RecId);
            }
        }
    }

    if (batchOpen)
    {
        this.ttsCommitTrace(5);
    }

    salesTable.skipBusinessEvents(true);
    salesTable.updateBackStatus();

    /**
    if (salesUpdateRemain)
    {
        // Recalculating Sales totals if any line is cancelled due to no stock availability as we are skipping it in SalesUpdateRemain class. so need to explicitly call the update to recalculate the totals and other related fields which are normally calculated in updateCorrespondingSalesOrder method of SalesUpdateRemain class.
        this.ttsBeginTrace();

        SalesTable salesTableTotalsUpdate = SalesTable::find(_salesTable.SalesId, true);

        if (salesTableTotalsUpdate.setEstimate())
        {
            salesTableTotalsUpdate.doUpdate();
        }

        this.ttsCommitTrace();
    }**/

    return qualifyingSalesLines;
}

/// <summary>
/// Checks if sales line is eligible for cancellation.
/// Implementated in derived classes.
/// </summary>
/// <param name = "_salesTable">Sales table</param>
/// <param name = "_salesLine">Sales line</param>
/// <param name = "_pickListOrderedQty">Set to yes if picking list to be generated by ordered qty</param>
/// <returns>True if valid; otherwise, false.</returns>
protected boolean cancelSalesLine(SalesTable _salesTable, SalesLine _salesLine, boolean _pickListOrderedQty)
{
    boolean ret = true;

    ret = (_salesTable.METAllowBackOrders == false && _pickListOrderedQty == false && _salesLine.reservedPhysicalInSalesUnit() == 0
            // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
            // For xDock, if there is a sales order line with reserved physical = 0 do not cancel it as it will be handled by the TO
            && !_salesTable.metSalesTable().InternalCrossDockOrder);

    return ret;
}

protected boolean cancelSalesLineV2(SalesTable _salesTable, 
    SalesLine _salesLine, 
    boolean _pickListOrderedQty)
{
    boolean ret = true;

    ret = (_salesTable.METAllowBackOrders == false && _pickListOrderedQty == false && this.getSalesLineReservPhysicalInSalesUnit(_salesLine) == 0
            // Bug 221621: CB238 - NDC / Int xDock: D365 functional warehouse processing (F/L) - Finalization error
            // For xDock, if there is a sales order line with reserved physical = 0 do not cancel it as it will be handled by the TO
            && !metSalesTable.InternalCrossDockOrder);

    return ret;
}

/// <summary>
/// Get the appropriate action to perform based on the configuration criteria
/// Below matrix is attached in BUG - 201881 for reference
/// </summary>
/// <param name = "_salesTable">SalesTable reference</param>
/// <returns>String value</returns>
public str getActionToPerform(SalesTable   _salesTable)
{
    str actionToPerfrom;
    metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId);

    if (inventParameter.METSupplyFromTransfer == NoYes::Yes) //Food entity
    {
        if (metSalesTable.InternalCrossDockOrder == NoYes::Yes  &&
            inventLocation.METCSDWarehouse == NoYes::No         &&
            inventLocation.METPickDirector == NoYes::No         &&
            inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractCreateOnlyTO;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::No         &&
                inventLocation.METCSDWarehouse == NoYes::Yes        &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::Yes)
        {
            actionToPerfrom = METConstants::SOExtractOrderedSOPickOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::No         &&
                inventLocation.METCSDWarehouse == NoYes::Yes        &&
                inventLocation.METPickDirector == NoYes::Yes        &&
                inventLocation.METWaveRequired == NoYes::Yes)
        {
            actionToPerfrom = METConstants::SOExtractUpdateStatusOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::No         &&
                inventLocation.METCSDWarehouse == NoYes::Yes        &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractUpdateStatusOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::No         &&
                inventLocation.METCSDWarehouse == NoYes::No         &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractReservedSOPickOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::Yes        &&
                inventLocation.METCSDWarehouse == NoYes::No         &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractReservedSOPickOnly;
        }
        // CB679 - Event order and Backorder processes for NDC & CSD -- Begin
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::Yes        &&
                inventLocation.METCSDWarehouse == NoYes::Yes        &&
                inventLocation.METPickDirector == NoYes::Yes        &&
                inventLocation.METWaveRequired == NoYes::Yes)
        {
            actionToPerfrom = METConstants::SOExtractUpdateStatusOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::Yes        &&
                inventLocation.METCSDWarehouse == NoYes::Yes        &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::Yes)
        {
            actionToPerfrom = METConstants::SOExtractOrderedSOPickOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::Yes        &&
                inventLocation.METCSDWarehouse == NoYes::Yes        &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractUpdateStatusOnly;
        }
        // CB679 - Event order and Backorder processes for NDC & CSD -- End
        else
        {
            actionToPerfrom = METConstants::SOExtractSkip;
        }
    }
    else // Liquor entity
    {
        if (metSalesTable.InternalCrossDockOrder == NoYes::Yes  &&
            _salesTable.METAllowBackOrders == NoYes::Yes        &&
            inventLocation.METCSDWarehouse == NoYes::No         &&
            inventLocation.METPickDirector == NoYes::No         &&
            inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractReservedSOPickAndTO;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::Yes     &&
            _salesTable.METAllowBackOrders == NoYes::No                 &&
            inventLocation.METCSDWarehouse == NoYes::No                 &&
            inventLocation.METPickDirector == NoYes::No                 &&
            inventLocation.METWaveRequired == NoYes::No)
        {
            // Bug 225259: CB238 - NDC / Int xDock: D365 functional warehouse processing Liquor LE SO extraction and TO extraction LSE004 and LTE003 substitution issues
            // Removed previous fix as generating the picking list with reserved qty = 0 is not throwing error anymore
            // Also it is now triggereing stock reservation which does the substitution for xDock
            actionToPerfrom = METConstants::SOExtractReservedSOPickAndTO;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::No         &&
                inventLocation.METCSDWarehouse == NoYes::No         &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractReservedSOPickOnly;
        }
        else if (metSalesTable.InternalCrossDockOrder == NoYes::No  &&
                _salesTable.METAllowBackOrders == NoYes::Yes        &&
                inventLocation.METCSDWarehouse == NoYes::No         &&
                inventLocation.METPickDirector == NoYes::No         &&
                inventLocation.METWaveRequired == NoYes::No)
        {
            actionToPerfrom = METConstants::SOExtractReservedSOPickOnly;
        }
        else
        {
            actionToPerfrom = METConstants::SOExtractSkip;
        }
    }
    return actionToPerfrom;
}

