/// <summary>
/// Method to trigger business event and do shipment load cleanup if necessary when SO extract is called from TO finalisation.
/// </summary>
/// <param name = "_forceTriggerBusinessEvent">Trigger business event</param>
public void finalThreadBusinessEventAndShipmentCleanup(boolean _forceTriggerBusinessEvent = true)
{
    if (_forceTriggerBusinessEvent || dataContract)
    {
        if (procMetrics)
        {
            procMetrics.startDescriptionTime(2, "@MET:METSOExtractTriggerBusinessEvent");
        }

        this.triggerBusinessEvent(wmsPickingRoute);

        if (dataContract)
        {
            container conShipmentIds = dataContract.parmShipmentIdList();
            SalesId csdSalesId = dataContract.parmCSDSalesId();
            str csdGuid = dataContract.parmCsdGuid();

            container conCsdOrder = dataContract.parmCSDSalesOrderList();

            if (csdSalesId && csdGuid && conLen(conCsdOrder) > 0 && dataContract.parmCSDSalesOrderExtractDateTime())
            {
                METWaveTable metWaveTable = METWaveTable::findByOrderExtractDateTimeAndGuid(dataContract.parmCSDSalesOrderExtractDateTime(), csdGuid);

                if (metWaveTable)
                {
                    metWaveTable.triggerWaveGeneratedBusinessEvent(conCsdOrder);
                }
            }

            METSalesOrderShipmentLoadHeader::cleanShipmentIfNoLines(conShipmentIds);
        }

        if (procMetrics)
        {
            procMetrics.endDescriptionTime(2);
        }
    }
}

/// <summary>
/// Posts the picking list into the SalesTable.
/// </summary>
/// <param name = "_salesTable">Sales table record</param>
/// <param name = "_pickListOrderedQty">Flag to indicate if pick list ordered quantity should be considered</param>
public void postPickingListV2(SalesTable _salesTable, boolean _pickListOrderedQty = false)
{
    // Due to performance issue with extraction process, this method is created to directly update the tables instead of using the standard picking list generation process. This method will update the tables as if the picking list is generated with all the lines and quantities using the SalesFormLetter classes. Refer the previous implementation of postPickingList method where the SalesFormLetter class is used.

    List                qualifyingSalesLineRecIds;

    try
    {
        if (_salesTable.SalesStatus != SalesStatus::Canceled)
        {
            reservedQtyInSalesUnitMap  = new Map(Types::Int64, Types::Real);
            reservedQtyInInventUnitMap = new Map(Types::Int64, Types::Real);

            processExtraction = false;

            if (procMetrics)
            {
                procMetrics.startDescriptionTime(6, "@MET:METSOExtractCalcQualifyingLines");
            }

            // Skip business events
            this.salesUpdateRemain().parmSkipBusinessEvents(true);

            qualifyingSalesLineRecIds = this.calcQueryV2(_salesTable, _pickListOrderedQty);

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(6, qualifyingSalesLineRecIds.elements());
                procMetrics.endDescriptionTime(6);
            }

            if (processExtraction == true)
            {
                this.ttsBeginTrace();

                if (procMetrics)
                {
                    procMetrics.startDescriptionTime(7, "@MET:METSOExtractPickingListCreation");
                }

                this.postPickingListDirect(_salesTable, _pickListOrderedQty, qualifyingSalesLineRecIds);

                if (wmsPickingRoute)
                {
                    this.updateWmsPickingRoute(wmsPickingRoute);
                }

                TransactionLog::create(TransactionLogType::SalesPickingList, "@SYS50969");

                TaxWorkRegulation::clearRegulation(tableNum(SalesTable), _salesTable.RecId);

                this.ttsCommitTrace(7);

                if (procMetrics)
                {
                    procMetrics.endDescriptionTime(7);
                }
            }
            else
            {
                if (!_salesTable.METAllowBackOrders && !metSalesTable.InternalCrossDockOrder)
                {
                    this.updateExtractedStatusOnSalesLine(_salesTable);
                }
            }

            if (!useLegacyPostProcessMode && !_salesTable.InterCompanyOrder)
            {
                this.insertPendingProcessRecord(_salesTable.SalesId);
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error ("@WAX:UpdateCancelled");
                isError = true;
            }
            else
            {
                retry;
            }
        }
        else
        {
            error ("@WAX:UpdateCancelled");
            isError = true;
        }
    }
    catch(Exception::DuplicateKeyException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                error ("@WAX:UpdateCancelled");
                isError = true;
            }
            else
            {
                retry;
            }
        }
        else
        {
            error ("@WAX:UpdateCancelled");
            isError = true;
        }
    }
    catch
    {
        error ("@WAX:UpdateCancelled");
        isError = true;
    }

    _salesTable.reread();
    _salesTable.selectForUpdate(true);
    _salesTable.metUpdateExtractStatus();

    if (!isError && !skipTMSProcess)
    {
        if (useLegacyPostProcessMode && _salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted)
        {
            if (procMetrics)
            {
                procMetrics.startDescriptionTime(8, "@MET:METSOExtractTMSEngineOrderProcess");
            }

            METTMSEngineOrderProccess  metTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderPickingList, wmsPickingRoute, wmsPickingRoute.PickingRouteID);
            metTMSEngineOrderProccess.run();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(8, 1);
                procMetrics.endDescriptionTime(8);
            }
        }
    }
}

protected void postPickingListDirect(SalesTable _salesTable, boolean _pickListOrderedQty, List _qualifyingSalesLines)
{
    boolean             isCSDPrint      = dataContract && dataContract.parmCSDSalesId() == dataContract.parmSalesId();
    InventLocation      inventLoc       = InventLocation::find(_salesTable.InventLocationId);
    WMSPickingRouteID   pickingRouteId  = NumberSeq::newGetNum(WMSParameters::numRefWMSPickingRouteId()).num();
    boolean             useQualityManagement = InventParameters::find().UseQualityManagement;

    // Create shipment and picking route headers
    WMSShipment wmsShipment = this.createWMSShipment();
    this.initWMSPickingRoute(_salesTable, inventLoc, pickingRouteId, wmsShipment);

    // Pre-fetch prior picked qtys per InventTransId (backorder path only)
    Map pickedQtyMap = _salesTable.METAllowBackOrders
      ? this.buildPickedQtyMap(_salesTable)
      : new Map(Types::String, Types::Real);

    // Process each qualifying sales line
    ListEnumerator  le = _qualifyingSalesLines.getEnumerator();
    SalesLine       salesLine;

    while (le.moveNext())
    {
        // Targeted clustered-index seek: fresh buffer with forUpdate lock inside ttsbegin
        select forupdate salesLine
            where salesLine.RecId == le.current();

        if (salesLine)
        {
            boolean         cwItem = PdsGlobal::pdsIsCWItem(salesLine.ItemId);
            InventQty       inventNow   = this.calcInventNow(salesLine, _pickListOrderedQty);

            if (!inventNow)
            {
                continue;
            }

            if (useQualityManagement)
            {
                InventQualityManagementBlockHandler::blockSalesPickingList(salesLine);
            }

            PdsCWInventQty cwQty = cwItem ? salesLine.pdsCWRemainInventPhysical : 0;

            // Create WMS pick order and assign to shipment
            WMSOrder  wmsOrder  = WMSOrderCreate::createOrUpdateWMSOrder(InventMovement::construct(salesLine),
                                                                        -inventNow,
                                                                        WMSOrderType::OrderPick,
                                                                        '',
                                                                        -cwQty);

            InventQty shipQty   = min(inventNow, wmsOrder.qtyNoShipment); // capture before updateShipment modifies buffer

            cwQty = cwItem ? min(cwQty, wmsOrder.PdsCWQtyNoShipment) : 0;

            wmsOrder.updateShipment(wmsShipment,
                shipQty,
                wmsPickingRoute.PickingRouteID,
                true,
                cwQty);

            if (useQualityManagement)
            {
                InventQualityManagementCreateHandler::createSalesPickingListAfterPost(salesLine, inventNow, cwQty);
            }

            if (_salesTable.InterCompanyCompanyId)
            {
                SalesLineType::construct(salesLine).interCompanyResetDeliverNow();
            }

            if (useLegacyPostProcessMode)
            {
                if (!_salesTable.METAllowBackOrders && !metSalesTable.InternalCrossDockOrder)
                {
                    if (shipQty < salesLine.RemainInventPhysical)  // only short picks need remainder cancellation
                    {
                        InventQty shipQtySales = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                        salesLine.ItemId,
                        salesLine.InventDimId,
                        shipQty,
                        salesLine.inventTable().inventUnitId(),
                        salesLine.SalesUnit,
                        NoYes::No,
                        NoYes::No);

                        salesLine.skipBusinessEvents(true);

                        this.salesUpdateRemain().updateExtractionDeliverRemainder(
                        salesLine,
                        shipQtySales,
                        shipQty,
                        cwQty);
                    }
                }
            }

            if (_salesTable.METAllowBackOrders)
            {
                METOrderExtractStatus lineStatus = this.resolveLineStatus(_salesTable, salesLine, shipQty, pickedQtyMap);
                this.updateMETSalesLineStatus(salesLine.RecId, lineStatus);
            }

            this.updateIntercompanySalesLine(salesLine);

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(7, 1);
            }
        }
    }

    // Batch updates: charges, deliver-now fields, extraction status
    this.batchUpdateAfterLoop(_salesTable);

    // Finalize route, sales table, and shipment
    this.activatePickingRoute();
    this.createPickingRouteLink(_salesTable);
    this.finalizeSalesTableStatus(_salesTable);
    this.finalizeShipment(wmsShipment);

    METWMSOrderTransPickListFieldsPopulator::updateMETWMSOrderTrans(wmsPickingRoute.pickingRouteID);

    // Create TMS shipment load
    METOrderShipmentLoadCreation::construct(METOrderTransactionType::SalesOrder, _salesTable.SalesId)
      .createShippmentLoad(true, false);

    if (!isCSDPrint)
    {
        info(strFmt("@MET:PickListForReservedQty", _salesTable.SalesId));
    }
    else
    {
        info(strFmt("@MET:SOPickListForOrderQty", _salesTable.SalesId));
    }

    if (procMetrics)
    {
        procMetrics.incProcessedCount(1);
    }
}

// Creates and inserts WMSShipment record
private WMSShipment createWMSShipment()
{
    WMSShipment wmsShipment;
    wmsShipment.clear();
    wmsShipment.initTypeOrderPick();
    wmsShipment.skipBusinessEvents(true);
    METGlobal::validateWriteRecordCheck(wmsShipment);
    wmsShipment.insert();
    return wmsShipment;
}

// Populates and inserts the class-level wmsPickingRoute
private void initWMSPickingRoute(SalesTable _salesTable, InventLocation _inventLoc, WMSPickingRouteID _pickingRouteId, WMSShipment _wmsShipment)
{
    wmsPickingRoute.clear();
    wmsPickingRoute.PickingRouteID                  = _pickingRouteId;
    wmsPickingRoute.ParmId                          = _salesTable.SalesId;
    wmsPickingRoute.Customer                        = _salesTable.CustAccount;
    wmsPickingRoute.DeliveryPostalAddress           = _salesTable.DeliveryPostalAddress;
    wmsPickingRoute.DlvDate                         = _salesTable.ShippingDateConfirmed;
    wmsPickingRoute.DlvModeId                       = _salesTable.DlvMode;
    wmsPickingRoute.DlvTermId                       = _salesTable.DlvTerm;

    // DEV NOTE: Standard V1 path (SalesPickingListJournalCreate.initJournalHeader) initialises
    // wmsPickingRoute via wmsPickingRoute.initTypeOrderPick() which sets ExpeditionStatus = Registered.
    // V2 sets Activated directly here for simplicity. activatePickingRoute() re-updates it below.
    // If issues arise with downstream processes reading ExpeditionStatus = Registered between
    // creation and activation, change this to Registered and let activatePickingRoute() set Activated.
    wmsPickingRoute.ExpeditionStatus                = WMSExpeditionStatus::Activated;

    wmsPickingRoute.InventLocationId                = _salesTable.InventLocationId;
    wmsPickingRoute.PrintMgmtSiteId                 = _inventLoc.InventSiteId;
    wmsPickingRoute.ShipmentId                      = _wmsShipment.ShipmentId;
    wmsPickingRoute.ShipmentType                    = WMSShipmentType::OrderPick;
    wmsPickingRoute.TransRefId                      = _salesTable.SalesId;
    wmsPickingRoute.TransType                       = InventTransType::Sales;
    wmsPickingRoute.DeliveryName                    = _salesTable.DeliveryName;
    wmsPickingRoute.METTransferOrderPickingRouteId  = '';
    wmsPickingRoute.METExternalInvoicedSO           = NoYes::No;
    wmsPickingRoute.InterCompanyPosted              = _salesTable.InterCompanyOrigin != InterCompanyOrigin::Source ? NoYes::Yes : NoYes::No;
    wmsPickingRoute.skipBusinessEvents(true);
    METGlobal::validateWriteRecordCheck(wmsPickingRoute);
    wmsPickingRoute.insert();
}

// Pre-fetches sum of already-picked qty per InventTransId (one query for all lines)
private Map buildPickedQtyMap(SalesTable _salesTable)
{
    Map             pickedQtyMap = new Map(Types::String, Types::Real);
    WMSOrderTrans   wmsOrderTransPre;
    SalesLine       salesLineJoin;

    while select sum(Qty), InventTransId from wmsOrderTransPre
      group by wmsOrderTransPre.InventTransId
      exists join salesLineJoin
          where salesLineJoin.SalesId       == _salesTable.SalesId
             && salesLineJoin.InventTransId == wmsOrderTransPre.InventTransId
    {
        pickedQtyMap.add(wmsOrderTransPre.InventTransId, wmsOrderTransPre.Qty);
    }

    return pickedQtyMap;
}

// Returns qty to pick in inventory unit
private InventQty calcInventNow(SalesLine _salesLine, boolean _pickListOrderedQty)
{
    InventQty sourceQty;

    if (_pickListOrderedQty)
    {
        sourceQty = _salesLine.SalesQty;

        UnitOfMeasureSymbol inventUnit = _salesLine.inventTable().inventUnitId();

        if (_salesLine.SalesUnit == inventUnit)
        {
            return sourceQty;
        }

        sourceQty = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                                                                _salesLine.ItemId,
                                                                                _salesLine.InventDimId,
                                                                                sourceQty,
                                                                                _salesLine.SalesUnit,
                                                                                inventUnit,
                                                                                NoYes::No,
                                                                                NoYes::No);
    }
    else
    {
        sourceQty = this.getSalesLineReservPhysicalInInventUnit(_salesLine);
    }

    return sourceQty;
}

// Determines if this line is fully extracted or still open
private METOrderExtractStatus resolveLineStatus(SalesTable _salesTable, SalesLine _salesLine, InventQty _shipQty, Map _pickedQtyMap)
{
    // Cross-dock lines are always marked Extracted after Phase I picks them.
    // Phase II creates a TO for the unfulfilled remainder — re-extraction must not happen.
    if (!_salesTable.METAllowBackOrders || metSalesTable.InternalCrossDockOrder)
    {
        return METOrderExtractStatus::Extracted;
    }

    // Prior picks + this run = total picked so far
    InventQty totalPicked = (_pickedQtyMap.exists(_salesLine.InventTransId)
      ? _pickedQtyMap.lookup(_salesLine.InventTransId)
      : 0) + _shipQty;

    return (totalPicked == _salesLine.QtyOrdered)
      ? METOrderExtractStatus::Extracted
      : METOrderExtractStatus::Open;
}

// Updates METSalesLine extraction status for a given SalesLine RecId
private void updateMETSalesLineStatus(RefRecId _salesLineRecId, METOrderExtractStatus _lineStatus)
{
    METSalesLine metSalesLineUpd = METSalesLine::find(_salesLineRecId, true);

    if (metSalesLineUpd.RecId)
    {
        metSalesLineUpd.OrderExtractStatus = _lineStatus;
        metSalesLineUpd.skipBusinessEvents(true);
        metSalesLineUpd.update();
    }
}

// Batch updates for charge lines, deliver-now fields, and extraction status
private void batchUpdateAfterLoop(SalesTable _salesTable)
{
    SalesLine   salesLineJoin;
    MarkupTrans markupTransBatch;
    markupTransBatch.skipDataMethods(true);
    markupTransBatch.skipBusinessEvents(true);

    // Mark charge lines as picking list
    update_recordset markupTransBatch
      setting DocumentStatus = DocumentStatus::PickingList
      where   markupTransBatch.TransTableId   == tableNum(SalesLine)
           && markupTransBatch.Keep           == NoYes::No
           && markupTransBatch.DocumentStatus != DocumentStatus::PickingList
           && markupTransBatch.DocumentStatus != DocumentStatus::PackingSlip
      exists join salesLineJoin
          where salesLineJoin.SalesId    == _salesTable.SalesId
             && salesLineJoin.SalesStatus != SalesStatus::Canceled
             && salesLineJoin.RecId       == markupTransBatch.TransRecId;

    // Clear deliver-now quantities
    SalesLine salesLineDeliverNow;

    salesLineDeliverNow.skipBusinessEvents(true);

    while select forupdate salesLineDeliverNow
        where salesLineDeliverNow.SalesId    == _salesTable.SalesId
           && salesLineDeliverNow.SalesStatus != SalesStatus::Canceled
    {
        salesLineDeliverNow.SalesDeliverNow       = 0;
        salesLineDeliverNow.InventDeliverNow      = 0;
        salesLineDeliverNow.PdsCWInventDeliverNow = 0;
        salesLineDeliverNow.doUpdate();
    }

    if (!_salesTable.METAllowBackOrders)
    {
        METSalesLine metSalesLineBatch;
        SalesLine    salesLineStatus;

        metSalesLineBatch.skipDataMethods(true);
        metSalesLineBatch.skipBusinessEvents(true);

        update_recordset metSalesLineBatch
            setting OrderExtractStatus = METOrderExtractStatus::Extracted
        exists join salesLineStatus
            where salesLineStatus.SalesId       == _salesTable.SalesId
                && salesLineStatus.SalesStatus   != SalesStatus::Canceled
                && salesLineStatus.InventRefType != InventRefType::Purch
                && salesLineStatus.RecId         == metSalesLineBatch.SalesLine;
    }
}

public void updateExtractedStatusOnSalesLine(SalesTable _salesTable)
{
    METSalesLine metSalesLine;
    SalesLine    salesLine;

    ttsbegin;

    metSalesLine.skipDataMethods(true);
    metSalesLine.skipBusinessEvents(true);

    while select forupdate metSalesLine
            where metSalesLine.OrderExtractStatus != METOrderExtractStatus::Extracted
        exists join salesLine
            where salesLine.SalesId        == _salesTable.SalesId
                && salesLine.SalesStatus   != SalesStatus::Canceled
                && salesLine.InventRefType != InventRefType::Purch
                && salesLine.RecId         == metSalesLine.SalesLine
    {
        metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
        metSalesLine.update();
    }

    ttscommit;
}

// Activates picking route and its order trans lines
private void activatePickingRoute()
{
    WMSPickRouteStatusOnUpdate pickRouteStatus = SalesParameters::find().PickRouteStatusOnUpdate;

    if (pickRouteStatus != WMSPickRouteStatusOnUpdate::completed)
    {
        WMSOrderTrans wmsOrderTransBatch;
        wmsOrderTransBatch.skipDataMethods(true);
        wmsOrderTransBatch.skipBusinessEvents(true);

        update_recordset wmsOrderTransBatch
          setting ExpeditionStatus = WMSExpeditionStatus::Activated
          where wmsOrderTransBatch.RouteId == wmsPickingRoute.PickingRouteID;

        wmsPickingRoute.selectForUpdate(true);
        wmsPickingRoute.ExpeditionStatus   = WMSExpeditionStatus::Activated;
        wmsPickingRoute.ActivationDateTime = DateTimeUtil::getSystemDateTime();
        wmsPickingRoute.skipBusinessEvents(true);
        wmsPickingRoute.update();

        // Activate linked shipment
        WMSShipment wmsShipmentActivate = wmsPickingRoute.wmsShipment(true);
        if (wmsShipmentActivate.RecId)
        {
            wmsShipmentActivate.setStatus(NoYes::Yes, NoYes::No);
        }
    }
    else
    {
        wmsPickingRoute.skipBusinessEvents(true);
        wmsPickingRoute.updateRoute(pickRouteStatus);
    }
}

// Links the picking route back to the sales order
private void createPickingRouteLink(SalesTable _salesTable)
{
    WMSPickingRouteLink wmsPickingRouteLink;
    wmsPickingRouteLink.clear();
    wmsPickingRouteLink.initFromSalesTable(_salesTable);
    wmsPickingRouteLink.initFromWMSPickingRoute(wmsPickingRoute);
    wmsPickingRouteLink.skipBusinessEvents(true);
    METGlobal::validateWriteRecordCheck(wmsPickingRouteLink);
    wmsPickingRouteLink.insert();
}

// Updates sales table document status and header markup
private void finalizeSalesTableStatus(SalesTable _salesTable)
{
    SalesTable salesTableUpd = SalesTable::find(_salesTable.SalesId, true);
    salesTableUpd.skipBusinessEvents(true);
    salesTableUpd.updateDocumentStatus(DocumentStatus::PickingList);
    salesTableUpd.updateBackStatus();
    salesTableUpd.updateSalesType();

    Markup::updateMarkupAsPosted(_salesTable, DocumentStatus::PickingList);
}

// Sets shipment to Picked status and fills location if missing
private void finalizeShipment(WMSShipment _wmsShipment)
{
    _wmsShipment.selectForUpdate(true);
    _wmsShipment.reread();
    _wmsShipment.skipBusinessEvents(true);
    if (!_wmsShipment.InventLocationId)
    {
        WMSPickingRoute wmsPickingRouteForShipment;
        select firstonly wmsPickingRouteForShipment
          where wmsPickingRouteForShipment.ShipmentId == _wmsShipment.ShipmentId;

        _wmsShipment.InventLocationId = wmsPickingRouteForShipment.InventLocationId;
        _wmsShipment.InventSiteId     = InventLocation::find(wmsPickingRouteForShipment.InventLocationId).InventSiteId;
    }

    _wmsShipment.Status               = WMSShipmentStatus::Picked;
    _wmsShipment.PickExpeditionStatus = WMSExpeditionStatus::Started;
    _wmsShipment.doUpdate();
}

protected void updateIntercompanySalesLine(SalesLine _salesLine)
{
    // Replicates METSalesPickingListJournalPost_Extension.metUpdateOrigSalesOrder().
    // Only fires for derived intercompany lines (food entity IC fulfillment).
    // Always sets Extracted on the original SO line - _status parameter removed as it was never read.
    if (_salesLine.isDerivedIntercompanyLine() && _salesLine.InterCompanyInventTransId)
    {
        changecompany(_salesLine.salesTable().InterCompanyCompanyId)
        {
            PurchLine purchLine = PurchLine::findInventTransId(_salesLine.InterCompanyInventTransId);
            if (purchLine.InterCompanyInventTransId && purchLine.ItemRefType == InventRefType::Sales)
            {
                SalesLine origSalesLine = SalesLine::findInventTransId(purchLine.InventRefTransId);
                METSalesLine metICSalesLine = METSalesLine::find(origSalesLine.RecId, true);

                if (metICSalesLine)
                {
                    metICSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                    metICSalesLine.skipBusinessEvents(true);
                    metICSalesLine.doUpdate();
                }

                origSalesLine.salesTable(true).metUpdateExtractStatus();
            }
        }
    }
}

public SalesQtyReservPhysical getSalesLineReservPhysicalInSalesUnit(SalesLine _salesLine)
{
    SalesQtyReservPhysical reservPhysical;

    if (reservedQtyInSalesUnitMap.exists(_salesLine.RecId))
    {
        reservPhysical = reservedQtyInSalesUnitMap.lookup(_salesLine.RecId);
    }
    else
    {
        container reservedQty = _salesLine.metReservedPhysicalInSalesInventUnit();

        SalesQtyReservPhysical reservQtyinSalesUnit = conPeek(reservedQty, 1);
        SalesQtyReservPhysical reservQtyinInventUnit = conPeek(reservedQty, 2);

        reservedQtyInSalesUnitMap.add(_salesLine.RecId, reservQtyinSalesUnit);
        reservedQtyInInventUnitMap.add(_salesLine.RecId, reservQtyinInventUnit);

        reservPhysical = reservQtyinSalesUnit;
    }

    return reservPhysical;
}

public SalesQtyReservPhysical getSalesLineReservPhysicalInInventUnit(SalesLine _salesLine)
{
    SalesQtyReservPhysical reservPhysical;

    if (reservedQtyInInventUnitMap.exists(_salesLine.RecId))
    {
        reservPhysical = reservedQtyInInventUnitMap.lookup(_salesLine.RecId);
    }
    else
    {
        container reservedQty = _salesLine.metReservedPhysicalInSalesInventUnit();

        SalesQtyReservPhysical reservQtyinSalesUnit = conPeek(reservedQty, 1);
        SalesQtyReservPhysical reservQtyinInventUnit = conPeek(reservedQty, 2);

        reservedQtyInSalesUnitMap.add(_salesLine.RecId, reservQtyinSalesUnit);
        reservedQtyInInventUnitMap.add(_salesLine.RecId, reservQtyinInventUnit);

        reservPhysical = reservQtyinInventUnit;
    }

    return reservPhysical;
}

public void performSOGuideCheck()
{
    SalesLine               salesLine;
    METSalesLine            metSalesLine;
    METInventItemOrderSetup metInventItemOrderSetup;
    InventDim               inventDim;
    CustTable               custTable; 
    LogisticsPostalAddress  deliveryAddress;
    METSalesOrderGuideItem  salesOrderGuideItemCustomerOnlySellTo, salesOrderGuideItemCustomerOperationsGroupOnlySellTo, salesOrderGuideItemSiteOnlySellTo, salesOrderGuideItemStateOnlySellTo, salesOrderGuideItemCustomerDoNotSellTo, salesOrderGuideItemCustomerOperationsGroupDoNotSellTo, salesOrderGuideItemSiteDoNotSellTo, salesOrderGuideItemStateDoNotSellTo;

    int batchCount = 0;
    boolean batchOpen = false;

    salesTable.reread();

    if (salesTable.METOrderExtractStatus != METOrderExtractStatus::Open && salesTable.METOrderExtractStatus != METOrderExtractStatus::ReadyForExtract)
    {
        return;
    }

    this.salesUpdateRemain().parmSkipBusinessEvents(true);

    select firstonly METCustOperGroupId
        from custTable
        where custTable.AccountNum == salesTable.CustAccount;

    while select salesLine
            where salesLine.SalesStatus == SalesStatus::Backorder
            && salesLine.SalesId == salesTable.SalesId
        join InventSiteId from inventDim
            where inventDim.InventDimId == salesLine.InventDimId
        join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
        outer join ItemStatus, RecId from metInventItemOrderSetup
            where metInventItemOrderSetup.ItemId == salesLine.ItemId
            && METInventItemOrderSetup.SiteId == inventDim.InventSiteId
        outer join State from deliveryAddress
            where deliveryAddress.Location == salesLine.DeliveryPostalAddress
        outer join RecId from salesOrderGuideItemCustomerOnlySellTo
            where salesOrderGuideItemCustomerOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::Customer
            && salesOrderGuideItemCustomerOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemCustomerOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemCustomerOperationsGroupOnlySellTo
            where salesOrderGuideItemCustomerOperationsGroupOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::CustomerOperationsGroup
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemSiteOnlySellTo
            where salesOrderGuideItemSiteOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemSiteOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::Site
            && salesOrderGuideItemSiteOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemSiteOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemSiteOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemStateOnlySellTo
            where salesOrderGuideItemStateOnlySellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemStateOnlySellTo.ReferenceType == METSalesOrderGuideReferenceType::State
            && salesOrderGuideItemStateOnlySellTo.Type == METSalesOrderGuideType::OnlySellTo
            && salesOrderGuideItemStateOnlySellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemStateOnlySellTo.Reference != ''
        outer join RecId from salesOrderGuideItemCustomerDoNotSellTo
            where salesOrderGuideItemCustomerDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::Customer
            && salesOrderGuideItemCustomerDoNotSellTo.Reference == salesLine.CustAccount
            && salesOrderGuideItemCustomerDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemCustomerDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerDoNotSellTo.Reference != ''
        outer join RecId from salesOrderGuideItemCustomerOperationsGroupDoNotSellTo
            where salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::CustomerOperationsGroup
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Reference == custTable.METCustOperGroupId
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.Reference != ''
        outer join RecId from salesOrderGuideItemSiteDoNotSellTo
            where salesOrderGuideItemSiteDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemSiteDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::Site
            && salesOrderGuideItemSiteDoNotSellTo.Reference == inventDim.InventSiteId
            && salesOrderGuideItemSiteDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemSiteDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemSiteDoNotSellTo.Reference != ''
        outer join RecId from salesOrderGuideItemStateDoNotSellTo
            where salesOrderGuideItemStateDoNotSellTo.ItemId == salesLine.ItemId
            && salesOrderGuideItemStateDoNotSellTo.ReferenceType == METSalesOrderGuideReferenceType::State
            && salesOrderGuideItemStateDoNotSellTo.Reference == deliveryAddress.State
            && salesOrderGuideItemStateDoNotSellTo.Type == METSalesOrderGuideType::DoNotSellTo
            && salesOrderGuideItemStateDoNotSellTo.Status == METEnabledDisabled::Enable
            && salesOrderGuideItemStateDoNotSellTo.Reference != ''
    {
        if (metInventItemOrderSetup.RecId
            && metInventItemOrderSetup.ItemStatus != METConstants::Active
            && metSalesLine.ReasonId != METConstants::NewReasonCode 
            && metSalesLine.ReasonId != METConstants::DEL)
        {
            if (!batchOpen)
            {
                this.ttsBeginTrace();
                batchOpen = true;
            }

            metSalesLine.selectForUpdate(true);
            metSalesLine.ReasonId = METConstants::NewReasonCode;
            metSalesLine.skipBusinessEvents(true);
            metSalesLine.update();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(2, 1);
            }

            batchCount++;
            if (batchCount >= batchTransactionCommit)
            {
                this.ttsCommitTrace(2);
                batchOpen = false;
                batchCount = 0;
            }

            continue;
        }

        // 1st priority: Customer only sell-to
        if (salesOrderGuideItemCustomerOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                metSalesLine.selectForUpdate(true);

                if (salesOrderGuideItemCustomerOnlySellTo.RecId && salesOrderGuideItemCustomerOnlySellTo.Reference == salesLine.CustAccount)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemCustomerOnlySellTo.RecId && salesOrderGuideItemCustomerOnlySellTo.Reference != salesLine.CustAccount)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 2nd priority: Customer do not sell-to
        if (salesOrderGuideItemCustomerDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                salesLine.selectForUpdate(true);
                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 3rd priority: Customer operations group only sell-to
        if (salesOrderGuideItemCustomerOperationsGroupOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                metSalesLine.selectForUpdate(true);
                if (salesOrderGuideItemCustomerOperationsGroupOnlySellTo.RecId && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Reference == custTable.METCustOperGroupId)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemCustomerOperationsGroupOnlySellTo.RecId && salesOrderGuideItemCustomerOperationsGroupOnlySellTo.Reference != custTable.METCustOperGroupId)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 4th priority: Customer operations group do not sell-to
        if (salesOrderGuideItemCustomerOperationsGroupDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                salesLine.selectForUpdate(true);
                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 5th priority: Site only sell-to
        if (salesOrderGuideItemSiteOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                metSalesLine.selectForUpdate(true);

                if (salesOrderGuideItemSiteOnlySellTo.RecId && salesOrderGuideItemSiteOnlySellTo.Reference == inventDim.InventSiteId)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }

                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemSiteOnlySellTo.RecId && salesOrderGuideItemSiteOnlySellTo.Reference != inventDim.InventSiteId)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 6th priority: Site do not sell-to
        if (salesOrderGuideItemSiteDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                salesLine.selectForUpdate(true);

                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 7th priority: State only sell-to
        if (salesOrderGuideItemStateOnlySellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                metSalesLine.selectForUpdate(true);

                if (salesOrderGuideItemStateOnlySellTo.RecId && salesOrderGuideItemStateOnlySellTo.Reference == deliveryAddress.State)
                {
                    metSalesLine.ReasonId = '';
                }
                else
                {
                    metSalesLine.ReasonId = METConstants::NIRReasonCode;
                    metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                }

                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (salesOrderGuideItemStateOnlySellTo.RecId && salesOrderGuideItemStateOnlySellTo.Reference != deliveryAddress.State)
                {
                    salesLine.selectForUpdate(true);
                    if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                    {
                        this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                    }
                    else
                    {
                        this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                    }
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        // 8th priority: State do not sell-to
        if (salesOrderGuideItemStateDoNotSellTo.RecId)
        {
            if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != METConstants::NIRReasonCode)
            {
                if (!batchOpen)
                {
                    this.ttsBeginTrace();
                    batchOpen = true;
                }

                salesLine.selectForUpdate(true);
                metSalesLine.selectForUpdate(true);
                metSalesLine.ReasonId = METConstants::NIRReasonCode;
                metSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                metSalesLine.skipBusinessEvents(true);
                metSalesLine.update();

                if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
                {
                    this.salesUpdateRemain().updateCatchWeightExtractionDeliverRemainder(salesLine, 0);
                }
                else
                {
                    this.salesUpdateRemain().updateExtractionDeliverRemainder(salesLine, 0, 0, 0);
                }

                batchCount++;
                if (batchCount >= batchTransactionCommit)
                {
                    this.ttsCommitTrace(2);
                    batchOpen = false;
                    batchCount = 0;
                }

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(2, 1);
                }
            }

            continue;
        }

        if (metSalesLine.ReasonId != METConstants::DEL && metSalesLine.ReasonId != '')
        {
            if (!batchOpen)
            {
                this.ttsBeginTrace();
                batchOpen = true;
            }

            metSalesLine.selectForUpdate(true);
            metSalesLine.ReasonId = '';
            metSalesLine.skipBusinessEvents(true);
            metSalesLine.update();

            batchCount++;
            if (batchCount >= batchTransactionCommit)
            {
                this.ttsCommitTrace(2);
                batchOpen = false;
                batchCount = 0;
            }

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(2, 1);
            }
        }
    }

    if (batchOpen)
    {
        this.ttsCommitTrace(2);
    }
}

public void ttsBeginTrace()
{
    if (procMetrics)
    {
        procMetrics.ttsBeginTrace();
    }
    else
    {
        ttsbegin;
    }
}

public void ttsCommitTrace(int _slot = 0)
{
    if (procMetrics)
    {
        if (_slot > 1)
        {
            procMetrics.startDualWriteTime(_slot);
        }

        procMetrics.ttsCommitTrace();

        if (_slot > 1)
        {
            procMetrics.endDualWriteTime(_slot);
        }
    }
    else
    {
        ttscommit;
    }
}

private void insertPendingProcessRecord(SalesId _salesId)
{
    METOrderExtractionPendingProcess pendingRecord;

    ttsbegin;
    pendingRecord.SalesId         = _salesId;
    pendingRecord.Status          = METOrderExtractionPendingProcessStatus::Pending;
    pendingRecord.ActionToPerform = actionToPerform;
    pendingRecord.PickingRouteID  = wmsPickingRoute.PickingRouteID;
    pendingRecord.insert();
    ttscommit;
}
